mkitem!{mkimpl!{impl CodegenFnAttrs { pub const EMPTY : & 'static Self = & Self :: new () ; pub const fn new () -> CodegenFnAttrs { CodegenFnAttrs { flags : CodegenFnAttrFlags :: empty () , inline : InlineAttr :: None , optimize : OptimizeAttr :: Default , symbol_name : None , link_ordinal : None , target_features : vec ! [] , safe_target_features : false , linkage : None , import_linkage : None , link_section : None , no_sanitize : SanitizerSet :: empty () , instruction_set : None , alignment : None , patchable_function_entry : None , } } # [doc = " Returns `true` if it looks like this symbol needs to be exported, for example:"] # [doc = ""] # [doc = " * `#[no_mangle]` is present"] # [doc = " * `#[export_name(...)]` is present"] # [doc = " * `#[linkage]` is present"] # [doc = ""] # [doc = " Keep this in sync with the logic for the unused_attributes for `#[inline]` lint."] pub fn contains_extern_indicator (& self) -> bool { if self . flags . contains (CodegenFnAttrFlags :: FOREIGN_ITEM) { return false ; } self . flags . contains (CodegenFnAttrFlags :: NO_MANGLE) || self . flags . contains (CodegenFnAttrFlags :: RUSTC_STD_INTERNAL_SYMBOL) || self . symbol_name . is_some () || match self . linkage { None | Some (Linkage :: Internal) => false , Some (_) => true , } } }}}